var getPackageAuthor = (packageName) => {
  if (packageName.startsWith("@tsci/")) {
    return packageName.split("/")[1].split(".")[0];
  }
  if (packageName.includes("/")) {
    return packageName.split("/")[0].replace("@", "");
  }
  return "";
};

