// lib/server/EventsWatcher.ts
import { EventEmitter as EventEmitter2 } from "events";

class EventsWatcher extends EventEmitter2 {
  lastPollTime;
  pollInterval;
  baseUrl;
  polling = false;
  timeoutId;
  constructor(baseUrl = "http://localhost:3000", pollInterval = 1000) {
    super();
    this.baseUrl = baseUrl;
    this.pollInterval = pollInterval;
    this.lastPollTime = new Date().toISOString();
  }
  async start() {
    if (this.polling)
      return;
    this.polling = true;
    await this.poll();
  }
  stop() {
    this.polling = false;
    if (this.timeoutId) {
      clearTimeout(this.timeoutId);
    }
  }
  async poll() {
    if (!this.polling)
      return;
    try {
      const response = await fetch(`${this.baseUrl}/api/events/list?since=${encodeURIComponent(this.lastPollTime)}`);
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      const data = await response.json();
      const latestEvent = data.event_list[data.event_list.length - 1];
      this.lastPollTime = latestEvent ? latestEvent.created_at : new Date().toISOString();
      data.event_list.forEach((event) => {
        this.emit(event.event_type, event);
        this.emit("*", event);
      });
    } catch (error) {
      this.emit("error", error);
    }
    this.timeoutId = globalThis.setTimeout(() => this.poll(), this.pollInterval);
  }
}

