// lib/utils/prompts.ts
var prompts = (...args) => {
  const [promptOrPromptArray] = args;
  const promptArray = Array.isArray(promptOrPromptArray) ? promptOrPromptArray : [promptOrPromptArray];
  if (!shouldBeInteractive()) {
    const result = {};
    promptArray.forEach((prompt) => {
      if (prompt.type === "confirm") {
        result[prompt.name] = true;
        return;
      } else if (prompt.initial) {
        result[prompt.name] = prompt.initial;
        return;
      } else if (prompt.type === "select" && prompt.choices && Array.isArray(prompt.choices)) {
        const selectedChoice = prompt.choices.find((c) => c.selected);
        if (!selectedChoice) {
          throw new Error(`No default/selected choice found for prompt: ${JSON.stringify(prompt, null, "  ")}. Cannot execute non-interactively`);
        }
        result[prompt.name] = selectedChoice.value;
        return;
      }
      throw new Error(`Can't answer prompt without being interactive: ${JSON.stringify(prompt, null, "  ")}`);
    });
    return result;
  }
  return import_prompts.default(...args);
};
