// lib/dependency-analysis/getLocalFileDependencies.ts
import * as ts2 from "typescript";
import * as path29 from "path";
import * as fs26 from "fs";
function getLocalFileDependencies(pathToTsxFile) {
  const absolutePath = path29.resolve(pathToTsxFile);
  const baseDir = path29.dirname(absolutePath);
  const content = fs26.readFileSync(absolutePath, "utf-8");
  const sourceFile = ts2.createSourceFile(absolutePath, content, ts2.ScriptTarget.Latest, true);
  const dependencies = new Set;
  function visit(node) {
    if (ts2.isImportDeclaration(node) || ts2.isExportDeclaration(node)) {
      const moduleSpecifier = node.moduleSpecifier;
      if (moduleSpecifier && ts2.isStringLiteral(moduleSpecifier)) {
        const importPath = moduleSpecifier.text;
        if (importPath.startsWith(".")) {
          resolveAndAddDependency(importPath);
        }
      }
    }
    if (ts2.isCallExpression(node) && node.expression.kind === ts2.SyntaxKind.ImportKeyword) {
      const argument = node.arguments[0];
      if (argument && ts2.isStringLiteral(argument)) {
        const importPath = argument.text;
        if (importPath.startsWith(".")) {
          resolveAndAddDependency(importPath);
        }
      }
    }
    ts2.forEachChild(node, visit);
  }
  function resolveAndAddDependency(importPath) {
    const extensions = [
      ".tsx",
      ".ts",
      ".jsx",
      ".js",
      ".css",
      ".scss",
      ".sass",
      ".less"
    ];
    let resolvedPath = path29.resolve(baseDir, importPath);
    if (fs26.existsSync(resolvedPath)) {
      dependencies.add(resolvedPath);
      return;
    }
    for (const ext of extensions) {
      const pathWithExt = resolvedPath + ext;
      if (fs26.existsSync(pathWithExt)) {
        dependencies.add(pathWithExt);
        return;
      }
    }
    if (fs26.existsSync(resolvedPath) && fs26.statSync(resolvedPath).isDirectory()) {
      for (const ext of extensions) {
        const indexPath = path29.join(resolvedPath, `index${ext}`);
        if (fs26.existsSync(indexPath)) {
          dependencies.add(indexPath);
          return;
        }
      }
    }
  }
  visit(sourceFile);
  return Array.from(dependencies);
}
